/// <summary>
/// Data contract for the <c>AAXTransferOrderShippedBusinessEvent</c> business event.
/// </summary>
[DataContract]
public final class AAXTransferOrderShippedBusinessEventContract extends BusinessEventsContract
{
    private DataAreaId legalEntity;
    private InventTransferId transferOrderId;
    private InventLocationId fromWarehouse;
    private InventLocationId toWarehouse;
    private int transferStatus;

}

