/// <summary>
/// Creates a new <c>AAXTransferOrderShippedBusinessEventContract</c> from the specified <c>InventTransferTable</c> record.
/// </summary>
/// <param name="_inventTransferTable">The source InventTransferTable record.</param>
/// <returns>A new populated instance of <c>AAXTransferOrderShippedBusinessEventContract</c>.</returns>
public static AAXTransferOrderShippedBusinessEventContract newFromInventTransferTable(InventTransferTable _inventTransferTable)
{
    var contract = new AAXTransferOrderShippedBusinessEventContract();
    contract.initialize(_inventTransferTable);

    return contract;
}

/// <summary>
/// Initializes the contract fields from the source record.
/// </summary>
/// <param name="_inventTransferTable">The source InventTransferTable record.</param>
private void initialize(InventTransferTable _inventTransferTable)
{
    legalEntity = _inventTransferTable.DataAreaId;
    transferOrderId = _inventTransferTable.TransferId;
    fromWarehouse = _inventTransferTable.InventLocationIdFrom;
    toWarehouse = _inventTransferTable.InventLocationIdTo;
    transferStatus = enum2int(_inventTransferTable.TransferStatus);
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
